package app.dayflow;
import android.widget.*;
import com.google.android.material.chip.*;
import org.json.*;
final class ProjectBoard {
 static void show(MainActivity a,String stage,int offset){LinearLayout page=a.fullPage("项目看板",a::home);page.addView(Ui.text(a,"项目与任务",24,true));ChipGroup tabs=new ChipGroup(a);tabs.setSingleSelection(true);String[] labels={"待开始","进行中","已完成"},values={"planned","doing","done"};for(int i=0;i<values.length;i++){String value=values[i];Chip chip=new Chip(a);chip.setText(labels[i]);chip.setCheckable(true);chip.setChecked(stage.equals(value));chip.setOnClickListener(v->show(a,value,0));tabs.addView(chip);}page.addView(tabs);try{JSONArray rows=Data.get(a).boardRows(stage,offset);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);com.google.android.material.card.MaterialCardView card=Ui.card(a);LinearLayout body=a.recordContents(r);body.addView(Ui.button(a,stage.equals("planned")?"开始进行":stage.equals("doing")?"完成任务":"恢复待开始",false,()->{try{JSONObject current=Data.get(a).find(r.getString("id"));if(current==null)throw new Exception("事项已不存在");if(stage.equals("doing")||stage.equals("done")){TaskActions.complete(a,current);if(stage.equals("done")){JSONObject restored=Data.get(a).find(r.getString("id"));if(restored!=null)Data.get(a).save(restored.put("board_status","planned"));}}else Data.get(a).save(current.put("board_status","doing"));a.changed();show(a,stage,offset);}catch(Exception e){a.message(e.getMessage());}}));card.addView(body);body.setOnClickListener(v->a.detail(r));page.addView(card);}if(rows.length()==0)page.addView(Ui.help(a,"这一列暂无任务"));if(offset>0)page.addView(Ui.button(a,"上一页",false,()->show(a,stage,Math.max(0,offset-40))));if(rows.length()==40)page.addView(Ui.button(a,"下一页",false,()->show(a,stage,offset+40)));}catch(Exception e){a.message(e.getMessage());}page.addView(Ui.button(a,"＋ 新建任务",true,()->a.newRecord("task")));}
}
